<script>
 import {onMount} from 'svelte';
 import {goto} from '$app/navigation';
 import {ArrowRight,ShieldCheck,HeartHandshake,UserRound,Eye,EyeOff} from 'lucide-svelte';
 import {supabase,api} from '$lib/auth.js';
 import {ROLE_PATH} from '$lib/config.js';
 let mode='login',email='',password='',fullName='',busy=false,notice='',failure='',showPassword=false;
 onMount(()=>{checkSession();const {data:{subscription}}=supabase.auth.onAuthStateChange((event)=>{if(event==='SIGNED_IN')setTimeout(checkSession,0);});return ()=>subscription.unsubscribe();});
 async function checkSession(){try{const {data:{session}}=await supabase.auth.getSession();if(session){const {profile}=await api('/me');await goto(ROLE_PATH[profile.role],{replaceState:true});}}catch(e){failure=e.message;}}
 async function submit(){busy=true;failure='';notice='';try{
  if(mode==='signup'){
   const {data,error}=await supabase.auth.signUp({email:email.trim(),password,options:{data:{full_name:fullName.trim()},emailRedirectTo:window.location.origin}});
   if(error)throw error;
   if(data.session)await checkSession();else {notice='Pendaftaran diterima. Cek email dan klik tautan verifikasi, lalu kembali ke halaman ini untuk login. Akun baru otomatis menjadi customer.';mode='login';password='';}
  }else{
   const {error}=await supabase.auth.signInWithPassword({email:email.trim(),password});
   if(error)throw error;await checkSession();
  }
 }catch(e){failure=e.message?.includes('Invalid login')?'Email atau kata sandi salah.':e.message?.includes('Email not confirmed')?'Verifikasi email terlebih dahulu. Cek kotak masuk dan folder spam.':e.message?.includes('rate limit')?'Terlalu banyak percobaan. Tunggu sebentar lalu coba lagi.':e.message||'Login tidak berhasil.';}finally{busy=false;}}
</script>
<svelte:head><title>Login — HEIJO Reflexology</title><meta name="description" content="Login administrator, terapis, dan customer HEIJO Reflexology."/></svelte:head>
<div class="auth-shell"><section class="brand-panel"><a class="brand" href="/" aria-label="HEIJO Reflexology"></a><div class="intro"><span class="tag">REFLEKSI & RELAKSASI</span><h1>Lepas lelah.<br/>Temukan nyaman.</h1><p>Ambil jeda untuk diri Anda. Jadwalkan refleksi dan nikmati waktu untuk kembali nyaman.</p><div class="roles"><div><ShieldCheck size={23}/><span><b>Administrator</b><small>Kelola akun dan seluruh reservasi</small></span></div><div><HeartHandshake size={23}/><span><b>Terapis</b><small>Fokus pada sesi yang ditugaskan</small></span></div><div><UserRound size={23}/><span><b>Customer</b><small>Atur jadwal dan lihat reservasi sendiri</small></span></div></div></div><p class="motto">Saatnya melepas lelah.</p></section><main><div class="login-box"><span class="eyebrow">SELAMAT DATANG</span><h2>{mode==='signup'?'Buat akun customer':'Masuk ke akun Anda'}</h2><p class="description">{mode==='signup'?'Daftar untuk membuat dan memantau reservasi refleksi.':'Dashboard terbuka sesuai hak akses akun Anda.'}</p><div class="tabs"><button class:active={mode==='login'} onclick={()=>{mode='login';failure='';}}>Login</button><button class:active={mode==='signup'} onclick={()=>{mode='signup';failure='';}}>Daftar customer</button></div>{#if failure}<div class="message error" role="alert">{failure}</div>{/if}{#if notice}<div class="message success" role="status">{notice}</div>{/if}<form onsubmit={e=>{e.preventDefault();submit();}}>{#if mode==='signup'}<label>Nama lengkap<input required maxlength="100" autocomplete="name" bind:value={fullName} placeholder="Nama Anda"/></label>{/if}<label>Email<input required type="email" autocomplete="email" bind:value={email} placeholder="nama@email.com"/></label><label>Kata sandi<div class="password"><input required type={showPassword?'text':'password'} minlength={mode==='signup'?8:1} maxlength="128" autocomplete={mode==='signup'?'new-password':'current-password'} bind:value={password} placeholder={mode==='signup'?'Minimal 8 karakter':'Masukkan kata sandi'}/><button type="button" aria-label={showPassword?'Sembunyikan kata sandi':'Tampilkan kata sandi'} onclick={()=>showPassword=!showPassword}>{#if showPassword}<EyeOff size={19}/>{:else}<Eye size={19}/>{/if}</button></div></label><button class="submit" disabled={busy}>{busy?'Memproses…':mode==='signup'?'Daftar customer':'Masuk ke dashboard'}<ArrowRight size={18}/></button></form><p class="access-note"><ShieldCheck size={17}/>Peran akun ditentukan oleh sistem. Akun terapis dan administrator dikelola oleh administrator.</p></div><small class="copyright">© 2026 HEIJO Reflexology</small></main></div>
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;font-family:Arial,Helvetica,sans-serif;color:#233e2e;background:#f7f8f3}:global(button),:global(input),:global(select){font:inherit}:global(button){cursor:pointer}:global(button:focus-visible),:global(a:focus-visible){outline:3px solid #b49b57;outline-offset:3px}.auth-shell{min-height:100vh;display:grid;grid-template-columns:1fr 1fr}.brand-panel{padding:50px 65px;background:#294b38;color:#eef2e4;display:flex;flex-direction:column}.intro{max-width:470px;margin:auto 0;padding:65px 0}.tag,.eyebrow{font-size:11px;letter-spacing:2px;font-weight:800;color:#b6b684}.intro h1{font-size:54px;line-height:1.08;letter-spacing:-2px;margin:23px 0}.intro>p{font-size:16px;line-height:1.8;color:#d1ddc6}.roles{display:grid;gap:24px;margin-top:43px}.roles>div{display:flex;align-items:center;gap:17px;color:#c1cba7}.roles b{display:block;font-size:15px;color:#f0f3e8}.roles small{display:block;font-size:13px;margin-top:7px;color:#c4d1b8}.motto{font-size:12px;line-height:1.7;color:#c3cda6;margin:0}main{padding:55px 50px;display:flex;flex-direction:column;align-items:center;justify-content:center}.login-box{max-width:410px;width:100%;margin:auto}.eyebrow{color:#829061}h2{font-size:31px;line-height:1.2;letter-spacing:-.7px;margin:16px 0}.description{font-size:14px;color:#63755d;line-height:1.7;margin-bottom:28px}.tabs{display:flex;border-bottom:1px solid #dfe6d7;margin-bottom:28px}.tabs button{background:none;border:0;padding:13px 19px;color:#728268;font-weight:700;border-bottom:3px solid transparent}.tabs button.active{color:#294b38;border-color:#294b38}form{display:grid;gap:20px}label{display:grid;gap:9px;font-size:14px;font-weight:700}input{width:100%;padding:14px;border:1px solid #d9e1d0;border-radius:7px;background:#fff;font-size:15px;color:#253e2a}input:focus{outline:2px solid #789763;outline-offset:2px}.password{position:relative}.password input{padding-right:50px}.password button{position:absolute;right:13px;top:13px;padding:0;border:0;background:none;color:#738565}.submit{margin-top:9px;border:0;padding:15px 20px;background:#355b40;color:#fff;border-radius:7px;display:flex;justify-content:space-between;align-items:center;font-weight:750;font-size:15px}.submit:disabled{opacity:.6;cursor:wait}.access-note{font-size:12px;color:#6a7b5e;line-height:1.8;border-top:1px solid #e1e7d8;padding-top:22px;margin-top:28px}.access-note :global(svg){vertical-align:middle;margin-right:6px}.copyright{color:#7b886e;margin-top:40px;font-size:11px}.message{padding:13px 15px;font-size:13px;line-height:1.7;border-radius:6px;margin-bottom:20px}.error{background:#fcebe4;color:#8c3e27}.success{background:#e7efdd;color:#44612f}@media(max-width:850px){.brand-panel{padding:35px}.intro h1{font-size:43px}main{padding:40px 28px}}@media(max-width:650px){.auth-shell{grid-template-columns:1fr}.brand-panel{padding:25px}.intro{padding:30px 0 0}.intro h1{font-size:36px;letter-spacing:-1px}.intro>p{font-size:14px}.roles,.motto{display:none}.intro h1 br{display:none}main{padding:35px 24px}.login-box{max-width:470px}h2{font-size:28px}}

:global(body){background:#f8f5ef;color:#063e2c}.brand-panel{background:radial-gradient(ellipse at 100% 100%,#a2803033,transparent 48%),linear-gradient(145deg,#002e21,#006345 65%,#003e2c);border-right:3px solid #c8a453;color:#fff}.tag{color:#ffdf8f}.intro h1{color:#fff}.intro>p,.roles small{color:#e2f1e8}.roles>div{color:#efcc75}.roles b{color:#fff}.motto{color:#f8dc93;font-weight:600}.eyebrow{color:#77581a}.description,.access-note{color:#365c49}.tabs{border-color:#ded7c7}.tabs button{color:#365b47}.tabs button.active{color:#004c34;border-color:#b88a2d}input{color:#103c2c;border-color:#c3cfc5}.submit{background:linear-gradient(115deg,#00563d,#003c2a);border:1px solid #bd984a;color:#fff;box-shadow:0 4px 16px #00442b1a}.password button{color:#275c43}.copyright{color:#405e4c}.success{background:#e6f2e9;color:#174a30}.error{color:#8a2e1c;background:#ffede5}.access-note{border-color:#ded7c7}.login-box h2{font-weight:800}.copyright{font-weight:600}
.brand{display:block;width:100%;aspect-ratio:3.5;background:#fff url('/heijo-logo.jpg') center 52% / 220% auto no-repeat;border-radius:7px;text-decoration:none;width:180px;max-width:100%}
</style>
